m/Y H:i') }}@else<span class="text-amber-900">Aucune session de caisse ouverte.</span> @if(auth()->user()->hasPermission('cash.open'))<a class="font-bold underline" href="{{ route('cash.my-session', ['return_to'=>'invoice']) }}">Ouvrir ma caisse</a>@endif @endif</div><label class="block text-sm font-semibold">Référence<input class="search-input mt-2 w-full" name="payment_reference" value="{{ old('payment_reference', $draft['payment_reference'] ?? '') }}"></label><label class="block text-sm font-semibold">Date de paiement<input class="search-input mt-2 w-full" type="date" name="payment_date" value="{{ old('payment_date', $draft['payment_date'] ?? now()->toDateString()) }}"></label></div></section>
