<script>
(() => {
    const form = document.getElementById('operator-invoice-form');
    const csrf = form.querySelector('input[name="_token"]').value;
    const customerSearch = document.getElementById('customer-search');
    const customerId = document.getElementById('customer_id');
    const customerResults = document.getElementById('customer-results');
    const customerEmpty = document.getElementById('customer-empty');
    const selectedCustomer = document.getElementById('selected-customer');
    const customerName = document.getElementById('selected-customer-name');
    const productSearch = document.getElementById('product-search');
    const productResults = document.getElementById('product-results');
    const productEmpty = document.getElementById('product-empty');
    const lines = document.getElementById('invoice-lines');
    let customerTimer;
    let productTimer;
    let customerController;
    let productController;
    const formatMoney = value => `${new Intl.NumberFormat('fr-FR', {maximumFractionDigits: 2}).format(value)} FCFA`;
    const draftLines = @json(old('lines', $draft['lines'] ?? []));
    const savedProducts = @json($draftProducts);
    const selected = new Map(savedProducts.map(product => [product.id, product]));
    const setCustomer = customer => { customerId.value = customer.id; customerName.textContent = customer.name; selectedCustomer.classList.remove('hidden'); customerResults.classList.add('hidden'); customerEmpty.classList.add('hidden'); customerSearch.value = customer.name; };
    const renderCustomers = data => { customerResults.replaceChildren(); data.forEach(customer => { const button = document.createElement('button'); button.type='button'; button.className='block w-full border-b p-3 text-left hover:bg-emerald-50'; button.innerHTML=`<strong></strong><small class="block text-slate-600"></small>`; button.querySelector('strong').textContent=customer.name; button.querySelector('small').textContent=[customer.phone,customer.email].filter(Boolean).join(' · '); button.addEventListener('click',()=>setCustomer(customer)); customerResults.append(button); }); customerResults.classList.toggle('hidden', data.length===0); customerEmpty.classList.toggle('hidden', data.length!==0); };
    customerSearch.addEventListener('input',()=>{ clearTimeout(customerTimer); if(customerController) customerController.abort(); const q=customerSearch.value.trim(); customerId.value=''; selectedCustomer.classList.add('hidden'); if(q.length<2){customerResults.classList.add('hidden');customerEmpty.classList.add('hidden');return;} customerTimer=setTimeout(async()=>{customerController=new AbortController();try{const response=await fetch(`{{ route('customers.search') }}?q=${encodeURIComponent(q)}`,{headers:{Accept:'application/json'},signal:customerController.signal});const json=await response.json();renderCustomers(json.data||[]);}catch(error){if(error.name!=='AbortError') customerEmpty.classList.remove('hidden');}},250);});
    document.getElementById('clear-customer')?.addEventListener('click',()=>{customerId.value='';customerSearch.value='';selectedCustomer.classList.add('hidden');customerSearch.focus();});
    document.getElementById('quick-customer-toggle')?.addEventListener('click',()=>document.getElementById('quick-customer-panel').classList.toggle('hidden'));
    document.getElementById('quick-type')?.addEventListener('change',event=>{const company=event.target.value!=='individual';document.getElementById('quick-legal-wrap').classList.toggle('hidden',!company);document.getElementById('quick-first-wrap').classList.toggle('hidden',company);document.getElementById('quick-last-wrap').classList.toggle('hidden',company);});
    document.getElementById('quick-customer-submit')?.addEventListener('click',async()=>{const error=document.getElementById('quick-customer-error');error.classList.add('hidden');const type=document.getElementById('quick-type').value;const body={type,legal_name:document.getElementById('quick-legal').value,first_name:document.getElementById('quick-first').value,last_name:document.getElementById('quick-last').value,phone:document.getElementById('quick-phone').value,email:document.getElementById('quick-email').value};try{const response=await fetch(`{{ route('customers.quick-store') }}`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(body)});const json=await response.json();if(!response.ok)throw new Error(Object.values(json.errors||{}).flat().join(' ' )||'Création impossible.');setCustomer(json.data);document.getElementById('quick-customer-panel').classList.add('hidden');}catch(exception){error.textContent=exception.message;error.classList.remove('hidden');}});
    const addLine = (product, line = {}) => {if(selected.has(product.id))return;selected.set(product.id,product);const index=lines.children.length;const row=document.createElement('div');row.className='grid gap-3 rounded-lg border p-3 md:grid-cols-[1fr_110px_130px_130px_150px] md:items-center';row.dataset.productId=product.id;row.dataset.price=product.price;row.dataset.tax=product.tax_rate;row.innerHTML=`<div><strong class="product-name"></strong><small class="block text-slate-500"></small><input type="hidden" name="lines[${index}][product_id]" value="${product.id}"><input class="line-quantity" type="hidden" name="lines[${index}][quantity]" value="${line.quantity||'1.000'}"><input class="line-discount" type="hidden" name="lines[${index}][discount_amount]" value="${line.discount_amount||'0.00'}"></div><label class="text-sm">Quantité<input class="search-input line-quantity-visible mt-1 w-full" type="number" min="0.001" step="0.001" value="${line.quantity||'1.000'}"></label><label class="text-sm">Remise<input class="search-input line-discount-visible mt-1 w-full" type="number" min="0" step="0.01" value="${line.discount_amount||'0.00'}"></label><div class="text-sm">Prix unitaire<strong class="block"></strong></div><div class="flex items-center justify-between text-sm"><span>Total ligne<strong class="line-total block"></strong></span><button type="button" class="remove-line text-red-700">Retirer</button></div>`;row.querySelector('.product-name').textContent=product.name;row.querySelector('small').textContent=product.description||'';row.querySelectorAll('strong')[1].textContent=formatMoney(Number(product.price));row.querySelector('.line-quantity-visible').addEventListener('input',event=>{row.querySelector('.line-quantity').value=event.target.value;updateTotals();});row.querySelector('.line-discount-visible').addEventListener('input',event=>{row.querySelector('.line-discount').value=event.target.value;updateTotals();});row.querySelector('.remove-line').addEventListener('click',()=>{selected.delete(product.id);row.remove();reindexLines();updateTotals();});lines.append(row);updateTotals();};
    const reindexLines=()=>[...lines.children].forEach((row,index)=>{row.querySelector('input[type=hidden]').name=`lines[${index}][product_id]`;row.querySelector('.line-quantity').name=`lines[${index}][quantity]`;row.querySelector('.line-discount').name=`lines[${index}][discount_amount]`;});
    const updateTotals=()=>{let subtotal=0,discountTotal=0,tax=0;[...lines.children].forEach(row=>{const base=Number(row.dataset.price)*Number(row.querySelector('.line-quantity').value||0);const discount=Number(row.querySelector('.line-discount').value||0);const taxable=Math.max(0,base-discount);const taxAmount=taxable*Number(row.dataset.tax)/100;subtotal+=base;discountTotal+=discount;tax+=taxAmount;row.querySelector('.line-total').textContent=formatMoney(taxable+taxAmount);});document.getElementById('subtotal-label').textContent=formatMoney(subtotal);document.getElementById('discount-label').textContent=formatMoney(discountTotal);document.getElementById('tax-label').textContent=formatMoney(tax);document.getElementById('total-label').textContent=formatMoney(subtotal-discountTotal+tax);};
    const renderProducts=data=>{productResults.replaceChildren();data.forEach(product=>{const button=document.createElement('button');button.type='button';button.className='block w-full border-b p-3 text-left hover:bg-emerald-50';button.innerHTML='<strong></strong><small class="block text-slate-600"></small>';button.querySelector('strong').textContent=product.name;button.querySelector('small').textContent=`${formatMoney(Number(product.price))} · TVA ${product.tax_rate}%`;button.addEventListener('click',()=>{addLine(product);productSearch.value='';productResults.classList.add('hidden');});productResults.append(button);});productResults.classList.toggle('hidden',data.length===0);productEmpty.classList.toggle('hidden',data.length!==0);};
    productSearch.addEventListener('input',()=>{clearTimeout(productTimer);if(productController)productController.abort();const q=productSearch.value.trim();if(q.length<2){productResults.classList.add('hidden');productEmpty.classList.add('hidden');return;}productTimer=setTimeout(async()=>{productController=new AbortController();try{const response=await fetch(`{{ route('products.search') }}?q=${encodeURIComponent(q)}`,{headers:{Accept:'application/json'},signal:productController.signal});const json=await response.json();renderProducts(json.data||[]);}catch(error){if(error.name!=='AbortError')productEmpty.classList.remove('hidden');}},250);});
    draftLines.forEach(line=>{const product=selected.get(line.product_id);if(product)addLine(product,line);});
    document.getElementById('take-payment')?.addEventListener('change',event=>document.getElementById('payment-fields').classList.toggle('hidden',!event.target.checked));
    const paymentMethod=document.getElementById('payment_method_id');const cashInfo=document.getElementById('cash-session-info');const bankInfo=document.getElementById('bank-account-info');const bankSelect=document.getElementById('bank_account_id');const togglePaymentAccount=()=>{const isCash=paymentMethod?.selectedOptions[0]?.dataset.code==='cash';cashInfo.classList.toggle('hidden',!isCash);bankInfo.classList.toggle('hidden',isCash||!bankSelect||bankSelect.options.length<2);if(bankSelect)bankSelect.required=!isCash&&bankSelect.options.length>1;};paymentMethod?.addEventListener('change',togglePaymentAccount);if(paymentMethod?.value)togglePaymentAccount();
    form.addEventListener('submit',event=>{if(!customerId.value){event.preventDefault();customerSearch.focus();alert('Sélectionnez un client dans les résultats.');}else if(lines.children.length===0){event.preventDefault();productSearch.focus();alert('Ajoutez au moins un produit ou service.');}});
})();
</script>
@endsection
